def add_search_word(words_to_add, queries):
    root = {'children': {}, 'is_end': False}

    def insert(word):
        node = root
        for ch in word:
            if ch not in node['children']:
                node['children'][ch] = {'children': {}, 'is_end': False}
            node = node['children'][ch]
        node['is_end'] = True

    def dfs(word, index, node):
        if index == len(word):
            return node['is_end']

        ch = word[index]
        if ch == '.':
            for child in node['children'].values():
                if dfs(word, index + 1, child):
                    return True
            return False
        else:
            child = node['children'].get(ch)
            if child is None:
                return False
            return dfs(word, index + 1, child)

    for word in words_to_add:
        insert(word)

    return [dfs(query, 0, root) for query in queries]

